def _active_issue_codes_from_memo(realism_memo_before_resolution: Optional[Dict[str, Any]]) -> List[str]:
  active_issues = _memo_issue_records(realism_memo_before_resolution, "remaining_issues", "issues")
  codes: List[str] = []
  seen = set()
  for item in active_issues:
    if not isinstance(item, dict):
      continue
    code = str(item.get("issue_code") or "").strip().lower()
    if not code or code in seen:
      continue
    seen.add(code)
    codes.append(code)
  return codes


def _issue_severity_label_from_score(score: Any) -> str:
  severity_score = int(_safe_float(score) or 0)
  if severity_score >= 85:
    return "high"
  if severity_score >= 60:
    return "medium"
  return "low"


def _numeric_solver_contract_issue_packet_map(
  numeric_solver_contract: Optional[Dict[str, Any]],
) -> Dict[str, Dict[str, Any]]:
  contract = numeric_solver_contract if isinstance(numeric_solver_contract, dict) else {}
  issue_packet_map: Dict[str, Dict[str, Any]] = {}
  for item in (contract.get("issue_target_packets") or []):
    if not isinstance(item, dict):
      continue
    issue_code = str(item.get("issue_code") or "").strip().lower()
    if not issue_code:
      continue
    issue_packet_map[issue_code] = copy.deepcopy(item)
  return issue_packet_map


def _numeric_solver_contract_baseline_quarter_map(
  numeric_solver_contract: Optional[Dict[str, Any]],
) -> Dict[int, Dict[str, Any]]:
  contract = numeric_solver_contract if isinstance(numeric_solver_contract, dict) else {}
  baseline_map: Dict[int, Dict[str, Any]] = {}
  for item in (contract.get("baseline_quarter_metrics") or []):
    if not isinstance(item, dict):
      continue
    quarter_index = int(_safe_float(item.get("quarter_index")) or 0)
    if quarter_index < 1:
      continue
    baseline_map[quarter_index] = copy.deepcopy(item)
  return baseline_map


def _build_deterministic_issue_packets(
  *,
  issue_status_records: Optional[List[Dict[str, Any]]],
  numeric_solver_contract: Optional[Dict[str, Any]] = None,
  prior_decision_payload: Optional[Dict[str, Any]] = None,
  current_finmo_json: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
  prior_decision = prior_decision_payload if isinstance(prior_decision_payload, dict) else {}
  prior_packets = (
    prior_decision.get("decision", {}).get("issue_packets")
    if isinstance(prior_decision.get("decision"), dict)
    else []
  )
  prior_packet_map: Dict[str, Dict[str, Any]] = {}
  for item in (prior_packets or []):
    if not isinstance(item, dict):
      continue
    issue_code = str(item.get("issue_code") or "").strip().lower()
    if issue_code:
      prior_packet_map[issue_code] = copy.deepcopy(item)

  issue_record_map: Dict[str, Dict[str, Any]] = {}
  issue_order: List[str] = []
  for item in _clone_issue_status_records(issue_status_records):
    normalized = _normalize_issue_record_to_controller_truth(item)
    issue_code = str(normalized.get("issue_code") or "").strip().lower()
    if not issue_code:
      continue
    if issue_code not in issue_order:
      issue_order.append(issue_code)
    issue_record_map[issue_code] = copy.deepcopy(normalized)

  contract_issue_packet_map = _numeric_solver_contract_issue_packet_map(numeric_solver_contract)
  baseline_quarter_map = _numeric_solver_contract_baseline_quarter_map(numeric_solver_contract)

  for issue_code in contract_issue_packet_map.keys():
    if issue_code not in issue_order:
      issue_order.append(issue_code)
  for issue_code in prior_packet_map.keys():
    if issue_code not in issue_order:
      issue_order.append(issue_code)

  quarter_count = max(
    _CONVERGENCE_DEFAULT_QUARTER_COUNT,
    len((((current_finmo_json or {}).get("quarter_rows") or []) if isinstance(current_finmo_json, dict) else [])),
    len(baseline_quarter_map),
  )
  packets: List[Dict[str, Any]] = []
  for issue_code in issue_order:
    record = issue_record_map.get(issue_code) or {}
    contract_packet = contract_issue_packet_map.get(issue_code) or {}
    prior_packet = prior_packet_map.get(issue_code) or {}
    issue_title = str(
      record.get("issue")
      or prior_packet.get("issue")
      or prior_packet.get("issue_summary")
      or _canonical_issue_title(issue_code, "")
      or issue_code
    ).strip()
    detail = str(record.get("detail") or prior_packet.get("detail") or "").strip()
    severity_score = int(
      _safe_float(record.get("remaining_issue_severity_score"))
      or _safe_float(contract_packet.get("remaining_issue_severity_score"))
      or 0
    )
    if severity_score <= 0:
      severity_score = 75
    metric_specs = _issue_metric_specs_for_record(
      record,
      current_finmo_json=copy.deepcopy(current_finmo_json if isinstance(current_finmo_json, dict) else {}),
      quarter_count=max(1, int(quarter_count or _CONVERGENCE_DEFAULT_QUARTER_COUNT)),
    )
    affected_quarters = sorted(
      {
        int(_safe_float(item) or 0)
        for item in (
          [
            int(_safe_float(spec.get("quarter_index")) or 0)
            for spec in (metric_specs or [])
            if int(_safe_float(spec.get("quarter_index")) or 0) >= 1
          ]
          or _normalize_realism_remaining_quarters(record.get("remaining_problem_quarters"))
          or contract_packet.get("remaining_problem_quarters")
          or prior_packet.get("affected_quarters")
          or []
        )
        if int(_safe_float(item) or 0) >= 1
      }
    )
    candidate_lever_ids: List[str] = []
    for lever_id in _preferred_issue_candidate_lever_ids(
      issue_record=record,
      contract_packet=contract_packet,
      prior_packet=prior_packet,
    ):
      if lever_id and lever_id not in candidate_lever_ids:
        candidate_lever_ids.append(lever_id)
    metric_targets = [
      str(item).strip()
      for item in (contract_packet.get("metric_targets") or [])
      if str(item).strip()
    ]
    if metric_specs:
      metric_targets = list(
        dict.fromkeys(
          [
            str(item.get("metric_name") or "").strip().lower()
            for item in metric_specs
            if str(item.get("metric_name") or "").strip()
          ]
        )
      )
    evidence_points: List[Dict[str, Any]] = []
    metric_spec_by_quarter: Dict[int, List[Dict[str, Any]]] = {}
    for spec in metric_specs:
      quarter_index = int(_safe_float(spec.get("quarter_index")) or 0)
      if quarter_index < 1:
        continue
      metric_spec_by_quarter.setdefault(quarter_index, []).append(copy.deepcopy(spec))
    for quarter_index in affected_quarters:
      baseline_metrics = baseline_quarter_map.get(quarter_index) or {}
      quarter_specs = metric_spec_by_quarter.get(quarter_index) or []
      metric_spec = quarter_specs[0] if quarter_specs else {}
      metric_name = str(
        metric_spec.get("metric_name")
        or next(
          (
            metric
            for metric in metric_targets
            if _safe_float((baseline_metrics or {}).get(metric)) is not None
          ),
          metric_targets[0] if metric_targets else "ending_cash",
        )
      ).strip().lower()
      observed_value = (
        float(_safe_float(metric_spec.get("actual_value")) or 0.0)
        if metric_spec
        else float(_safe_float((baseline_metrics or {}).get(metric_name)) or 0.0)
      )
      problem_statement = str(metric_spec.get("metric_definition") or "").strip()
      if not problem_statement:
        problem_statement = (
          f"{issue_title} remains materially open in quarter {quarter_index} and still requires an operationally credible fix."
        )
      evidence_points.append(
        {
          "quarter_index": quarter_index,
          "metric_name": metric_name,
          "observed_value": observed_value,
          "problem_statement": problem_statement,
        }
      )
    if not evidence_points:
      evidence_points.append(
        {
          "quarter_index": 1,
          "metric_name": metric_targets[0] if metric_targets else "ending_cash",
          "observed_value": 0.0,
          "problem_statement": (
            f"{issue_title} remains materially open and still requires a quantified, model-backed fix."
          ),
        }
      )
    success_criteria = [
      (
        f"{str(spec.get('metric_name') or '').strip()} is inside its acceptable repair boundary across the relevant quarters."
      )
      for spec in (metric_specs[:4] if metric_specs else [])
    ]
    if not success_criteria:
      success_criteria = [
        "The issue is no longer materially open in the affected quarters.",
      ]
    disallowed_fix_patterns = [
      "Do not rely on explanation-only justification without actual model changes.",
      "Do not leave the issue open in later quarters after improving only the early horizon.",
    ]
    for item in (prior_packet.get("disallowed_fix_patterns") or []):
      text = str(item or "").strip()
      if text and text not in disallowed_fix_patterns:
        disallowed_fix_patterns.append(text)
    packets.append(
      {
        "issue_code": issue_code,
        "issue": issue_title,
        "detail": detail,
        "issue_summary": issue_title,
        "severity": _issue_severity_label_from_score(severity_score),
        "root_cause": (
          str((metric_specs[0] if metric_specs else {}).get("metric_definition") or "").strip()
          or detail
          or issue_title
        ),
        "affected_quarters": affected_quarters or [1],
        "evidence_points": evidence_points,
        "candidate_lever_ids": candidate_lever_ids,
        "required_fix_shape": str(
          contract_packet.get("solver_objective")
          or prior_packet.get("required_fix_shape")
          or "align_issue_to_viable_quarter_shape"
        ).strip(),
        "success_criteria": success_criteria,
        "disallowed_fix_patterns": disallowed_fix_patterns,
        "remaining_issue_materiality": str(
          record.get("remaining_issue_materiality")
          or contract_packet.get("remaining_issue_materiality")
          or "material"
        ).strip().lower(),
        "remaining_issue_severity_score": severity_score,
        "remaining_problem_quarters": affected_quarters,
        "relevant_quarters": affected_quarters,
        "next_required_lever_ids": candidate_lever_ids,
        "metric_targets": metric_targets,
        "solver_objective": str(contract_packet.get("solver_objective") or "").strip(),
      }
    )
  return packets


def _build_issue_packets_from_issue_ledger(
  *,
  issue_status_records: Optional[List[Dict[str, Any]]],
  numeric_solver_contract: Optional[Dict[str, Any]] = None,
  prior_decision_payload: Optional[Dict[str, Any]] = None,
  current_finmo_json: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
  return _build_deterministic_issue_packets(
    issue_status_records=issue_status_records,
    numeric_solver_contract=numeric_solver_contract,
    prior_decision_payload=prior_decision_payload,
    current_finmo_json=current_finmo_json,
  )


def _realism_resolution_decision_contract_error(
  *,
  parsed: Optional[Dict[str, Any]],
  active_issue_codes: Optional[List[str]],
  required_target_quarters: Optional[List[int]] = None,
) -> Optional[str]:
  decision = parsed if isinstance(parsed, dict) else {}
  codes = [str(code or "").strip().lower() for code in (active_issue_codes or []) if str(code or "").strip()]
  required_quarters = sorted(
    {
      int(_safe_float(item) or 0)
      for item in (required_target_quarters or [])
      if int(_safe_float(item) or 0) >= 1
    }
  )
  if not codes:
    return None
  recommendation_mode = str(decision.get("recommendation_mode") or "").strip().lower()
  recommended_actions = [item for item in (decision.get("recommended_actions") or []) if isinstance(item, dict)]
  if recommendation_mode != "adjust":
    return (
      "Active realism issues were provided, so recommendation_mode must be 'adjust', "
      f"not {recommendation_mode or 'missing'}."
    )
  if not recommended_actions:
    return "Active realism issues were provided, but recommended_actions was empty."
  contract_error = _numeric_adjust_actions_contract_error(
    recommended_actions=recommended_actions,
    action_quarter_mode="target_quarters",
    require_issue_codes=True,
    required_target_quarters=required_quarters,
  )
  if contract_error:
    return contract_error
  return None


def _numeric_adjust_actions_contract_error(
  *,
  recommended_actions: Optional[List[Dict[str, Any]]],
  action_quarter_mode: str,
  require_issue_codes: bool = False,
  required_target_quarters: Optional[List[int]] = None,
  default_required_metric_keys: Optional[List[str]] = None,
) -> Optional[str]:
  normalized_actions = [item for item in (recommended_actions or []) if isinstance(item, dict)]
  required_quarters = sorted(
    {
      int(_safe_float(item) or 0)
      for item in (required_target_quarters or [])
      if int(_safe_float(item) or 0) >= 1
    }
  )
  fallback_required_metric_keys = [
    str(item).strip()
    for item in (
      default_required_metric_keys
      if isinstance(default_required_metric_keys, list)
      else _REQUIRED_SOLVER_TARGET_METRIC_KEYS
    )
    if str(item).strip()
  ]
  if not normalized_actions:
    return "At least one recommended_action is required for an adjust decision."
  all_metric_quarters: set[int] = set()
  for action in normalized_actions:
    action_id = str(action.get("action_id") or "").strip() or "action"
    if require_issue_codes:
      issue_codes = [
        str(item or "").strip()
        for item in (action.get("issue_codes") or [])
        if str(item or "").strip()
      ]
      if not issue_codes:
        return f"{action_id} must include non-empty issue_codes."
    allowed_levers = [
      str(item or "").strip()
      for item in (action.get("solver_allowed_lever_ids") or [])
      if str(item or "").strip()
    ]
    if not allowed_levers:
      return f"{action_id} must include non-empty solver_allowed_lever_ids."
    quarter_target_metrics = [item for item in (action.get("quarter_target_metrics") or []) if isinstance(item, dict)]
    if not quarter_target_metrics:
      return f"{action_id} must include quarter_target_metrics."
    action_required_metric_keys = _normalize_primary_target_metric_names(
      action.get("required_target_metric_keys") or []
    )
    if not action_required_metric_keys:
      action_required_metric_keys = copy.deepcopy(fallback_required_metric_keys)
    metric_quarter_set = {
      int(_safe_float(item.get("quarter_index")) or 0)
      for item in quarter_target_metrics
      if int(_safe_float(item.get("quarter_index")) or 0) >= 1
    }
    if action_quarter_mode == "target_quarters":
      expected_quarter_set = {
        int(_safe_float(q) or 0)
        for q in (action.get("target_quarters") or [])
        if int(_safe_float(q) or 0) >= 1
      }
      if not expected_quarter_set:
        return f"{action_id} must include non-empty target_quarters."
      if metric_quarter_set != expected_quarter_set:
        return (
          f"{action_id} target_quarters and quarter_target_metrics quarter_index set must match exactly. "
          f"target_quarters={sorted(expected_quarter_set)}, quarter_target_metrics={sorted(metric_quarter_set)}."
        )
    else:
      start_q = int(_safe_float(action.get("timing_start_q")) or 0)
      end_q = int(_safe_float(action.get("timing_end_q")) or 0)
      if start_q < 1 or end_q < start_q:
        return f"{action_id} must include a valid timing_start_q/timing_end_q window."
      expected_quarter_set = set(range(start_q, end_q + 1))
      if metric_quarter_set != expected_quarter_set:
        return (
          f"{action_id} timing window and quarter_target_metrics quarter_index set must match exactly. "
          f"timing_window={sorted(expected_quarter_set)}, quarter_target_metrics={sorted(metric_quarter_set)}."
        )
    all_metric_quarters.update(metric_quarter_set)
    for item in quarter_target_metrics:
      quarter_index = int(_safe_float(item.get("quarter_index")) or 0)
      if quarter_index < 1:
        return f"{action_id} quarter_target_metrics contained an invalid quarter_index."
      for metric_name in action_required_metric_keys:
        metric_value = _safe_float(item.get(metric_name))
        if metric_value is None:
          return (
            f"{action_id} quarter_target_metrics for Q{quarter_index} is missing a numeric value for {metric_name}. "
            "All required target lines must be preset numerically for every targeted quarter."
          )
        if float(metric_value) != float(int(round(float(metric_value)))):
          return (
            f"{action_id} quarter_target_metrics for Q{quarter_index} metric {metric_name} must be a whole-dollar integer value. "
            f"received={metric_value}."
          )
  if required_quarters:
    missing_required_quarters = [quarter for quarter in required_quarters if quarter not in all_metric_quarters]
    if missing_required_quarters:
      return (
        "Recommended actions did not provide full required quarter coverage. "
        f"Missing quarter_target_metrics for quarters {missing_required_quarters}."
      )
  return None


def _normalize_unified_mapped_repair_targets(raw_targets: Any) -> List[Dict[str, Any]]:
  normalized: List[Dict[str, Any]] = []
  seen: set[Tuple[str, str, Tuple[int, ...]]] = set()
  for item in (raw_targets or []):
    if not isinstance(item, dict):
      continue
    issue_code = str(item.get("issue_code") or "").strip().lower()
    target_metric_name = str(item.get("target_metric_name") or "").strip().lower()
    target_quarters = sorted(
      {
        int(_safe_float(quarter) or 0)
        for quarter in (item.get("target_quarters") or [])
        if int(_safe_float(quarter) or 0) >= 1
      }
    )
    if not issue_code or not target_metric_name or not target_quarters:
      continue
    mapping_key = (issue_code, target_metric_name, tuple(target_quarters))
    if mapping_key in seen:
      continue
    seen.add(mapping_key)
    normalized.append(
      {
        "issue_code": issue_code,
        "target_metric_name": target_metric_name,
        "target_quarters": copy.deepcopy(target_quarters),
      }
    )
  return normalized


def _declared_mapped_target_metric_names(
  lever_adjustments: Any,
) -> List[str]:
  out: List[str] = []
  for adjustment in (lever_adjustments or []):
    if not isinstance(adjustment, dict):
      continue
    for mapping in _normalize_unified_mapped_repair_targets(
      adjustment.get("mapped_repair_targets") or []
    ):
      metric_name = str(mapping.get("target_metric_name") or "").strip().lower()
      if metric_name and metric_name in _UNIFIED_ALLOWED_TARGET_METRIC_KEYS and metric_name not in out:
        out.append(metric_name)
  return out


def _repair_target_direct_target_metric_names(
  repair_target: Optional[Dict[str, Any]],
) -> List[str]:
  item = repair_target if isinstance(repair_target, dict) else {}
  lever_ids = [
    str((driver_path or {}).get("lever") or "").strip()
    for driver_path in (item.get("driver_paths") or [])
    if isinstance(driver_path, dict) and str((driver_path or {}).get("lever") or "").strip()
  ]
  return post_intake_direct_target_metric_names_for_levers(lever_ids)


def _merge_required_target_tolerances(
  raw_tolerances: Any,
  required_metric_names: Any,
) -> List[Dict[str, Any]]:
  merged = _normalize_unified_target_tolerances(raw_tolerances)
  existing_metric_names = {
    str(item.get("metric_name") or "").strip().lower()
    for item in merged
    if isinstance(item, dict) and str(item.get("metric_name") or "").strip()
  }
  for item in _default_unified_target_tolerances(required_metric_names):
    metric_name = str(item.get("metric_name") or "").strip().lower()
    if metric_name and metric_name not in existing_metric_names:
      merged.append(copy.deepcopy(item))
      existing_metric_names.add(metric_name)
  merged.sort(key=lambda item: str(item.get("metric_name") or "").strip().lower())
  return merged


def _augment_solver_quarter_target_metrics(
  *,
  raw_targets: Any,
  required_metric_names: Any,
  numeric_solver_contract: Optional[Dict[str, Any]] = None,
  required_target_quarters: Optional[List[int]] = None,
) -> List[Dict[str, Any]]:
  normalized_targets = _normalize_solver_quarter_target_metrics(raw_targets)
  _ = _normalize_primary_target_metric_names(required_metric_names)
  _ = numeric_solver_contract if isinstance(numeric_solver_contract, dict) else None
  _ = copy.deepcopy(required_target_quarters or [])
  return normalized_targets


def _repair_target_matches_declared_mapping(
  *,
  repair_target: Optional[Dict[str, Any]],
  target_metric_name: str,
  target_quarter_set: set[int],
) -> bool:
  item = repair_target if isinstance(repair_target, dict) else {}
  quarter = int(_safe_float(item.get("quarter")) or 0)
  if quarter < 1 or (target_quarter_set and quarter not in target_quarter_set):
    return False
  metric_candidates = set(_repair_target_direct_target_metric_names(item))
  return bool(target_metric_name and target_metric_name in metric_candidates)


def _declared_mapping_driver_paths_for_lever(
  *,
  issue_packet: Optional[Dict[str, Any]],
  lever_id: str,
  target_metric_name: str,
  target_quarters: Optional[List[int]],
) -> Tuple[List[Dict[str, Any]], List[int]]:
  packet = issue_packet if isinstance(issue_packet, dict) else {}
  normalized_quarters = sorted(
    {
      int(_safe_float(quarter) or 0)
      for quarter in (target_quarters or [])
      if int(_safe_float(quarter) or 0) >= 1
    }
  )
  target_quarter_set = set(normalized_quarters)
  matched_paths: List[Dict[str, Any]] = []
  covered_quarters: set[int] = set()
  for repair_target in (packet.get("repair_targets") or []):
    if not isinstance(repair_target, dict):
      continue
    if not _repair_target_matches_declared_mapping(
      repair_target=repair_target,
      target_metric_name=target_metric_name,
      target_quarter_set=target_quarter_set,
    ):
      continue
    repair_target_quarter = int(_safe_float(repair_target.get("quarter")) or 0)
    for driver_path in (repair_target.get("driver_paths") or []):
      if not isinstance(driver_path, dict):
        continue
      if str(driver_path.get("lever") or "").strip() != lever_id:
        continue
      matched_paths.append(copy.deepcopy(driver_path))
      if repair_target_quarter >= 1:
        covered_quarters.add(repair_target_quarter)
  return matched_paths, sorted(covered_quarters)


def _issue_packet_mapped_driver_lever_ids(
  issue_packet: Optional[Dict[str, Any]],
) -> List[str]:
  packet = issue_packet if isinstance(issue_packet, dict) else {}
  ordered_lever_ids: List[str] = []
  for repair_target in (packet.get("repair_targets") or []):
    if not isinstance(repair_target, dict):
      continue
    for driver_path in (repair_target.get("driver_paths") or []):
      if not isinstance(driver_path, dict):
        continue
      lever_id = str(driver_path.get("lever") or "").strip()
      if lever_id and lever_id not in ordered_lever_ids:
        ordered_lever_ids.append(lever_id)
  return ordered_lever_ids


def _deterministic_guidance_focus_issue_codes(
  deterministic_numeric_guidance: Optional[Dict[str, Any]],
) -> List[str]:
  guidance = deterministic_numeric_guidance if isinstance(deterministic_numeric_guidance, dict) else {}
  ordered_issue_codes: List[str] = []
  for issue_packet in (guidance.get("issue_repair_packets") or []):
    if not isinstance(issue_packet, dict):
      continue
    issue_code = str(issue_packet.get("issue_code") or "").strip().lower()
    if issue_code and issue_code not in ordered_issue_codes:
      ordered_issue_codes.append(issue_code)
    if len(ordered_issue_codes) >= _CONVERGENCE_MAX_FOCUS_ISSUES:
      break
  return ordered_issue_codes


def _issue_packet_declared_target_metric_names(
  issue_packet: Optional[Dict[str, Any]],
) -> List[str]:
  packet = issue_packet if isinstance(issue_packet, dict) else {}
  ordered_metric_names: List[str] = []
  allowed_primary_metrics = set(_UNIFIED_ALLOWED_TARGET_METRIC_KEYS)
  for metric_name in (
    str(item).strip().lower()
    for item in (packet.get("metric_targets") or [])
    if str(item).strip()
  ):
    if metric_name and metric_name in allowed_primary_metrics and metric_name not in ordered_metric_names:
      ordered_metric_names.append(metric_name)
  for metric_name in post_intake_direct_target_metric_names_for_levers(
    [
      *[
        str(item).strip()
        for item in (packet.get("next_required_lever_ids") or [])
        if str(item).strip()
      ],
      *[
        str(item).strip()
        for item in (packet.get("candidate_lever_ids") or [])
        if str(item).strip()
      ],
    ]
  ):
    if metric_name and metric_name in allowed_primary_metrics and metric_name not in ordered_metric_names:
      ordered_metric_names.append(metric_name)
  for repair_target in (packet.get("repair_targets") or []):
    if not isinstance(repair_target, dict):
      continue
    for metric_name in _repair_target_direct_target_metric_names(repair_target):
      if metric_name and metric_name in allowed_primary_metrics and metric_name not in ordered_metric_names:
        ordered_metric_names.append(metric_name)
  if ordered_metric_names:
    return ordered_metric_names
  return ordered_metric_names


def _issue_packet_required_lever_families(
  issue_packet: Optional[Dict[str, Any]],
) -> List[str]:
  packet = issue_packet if isinstance(issue_packet, dict) else {}
  ordered_families: List[str] = []

  def _append_family(raw_family: Any) -> None:
    family = str(raw_family or "").strip().lower()
    if family and family not in ordered_families:
      ordered_families.append(family)

  for raw_family in (packet.get("candidate_lever_families") or []):
    _append_family(raw_family)
  if ordered_families:
    return ordered_families

  for lever_id in (
    [
      str(item).strip()
      for item in (packet.get("next_required_lever_ids") or [])
      if str(item).strip()
    ]
    + [
      str(item).strip()
      for item in (packet.get("candidate_lever_ids") or [])
      if str(item).strip()
    ]
  ):
    _append_family(_lever_family_from_lever_id(lever_id))
  if ordered_families:
    return ordered_families

  for lever_id in _issue_packet_mapped_driver_lever_ids(packet):
    _append_family(_lever_family_from_lever_id(lever_id))
  if ordered_families:
    return ordered_families

  for repair_target in (packet.get("repair_targets") or []):
    if not isinstance(repair_target, dict):
      continue
    for driver_path in (repair_target.get("driver_paths") or []):
      if not isinstance(driver_path, dict):
        continue
      _append_family(driver_path.get("lever_family"))
      if ordered_families:
        continue
      _append_family(_lever_family_from_lever_id(driver_path.get("lever")))
  return ordered_families


def _preferred_issue_candidate_lever_ids(
  *,
  issue_record: Optional[Dict[str, Any]] = None,
  contract_packet: Optional[Dict[str, Any]] = None,
  prior_packet: Optional[Dict[str, Any]] = None,
) -> List[str]:
  record = issue_record if isinstance(issue_record, dict) else {}
  contract = contract_packet if isinstance(contract_packet, dict) else {}
  prior = prior_packet if isinstance(prior_packet, dict) else {}
  mapped_candidates: List[str] = []
  for lever_id in (
    [
      str(item).strip()
      for item in (
        contract.get("next_required_lever_ids")
        or contract.get("candidate_lever_ids")
        or []
      )
      if str(item).strip()
    ]
    + [
      str(item).strip()
      for item in (
        prior.get("candidate_lever_ids")
        or prior.get("next_required_lever_ids")
        or []
      )
      if str(item).strip()
    ]
  ):
    if lever_id and lever_id not in mapped_candidates:
      mapped_candidates.append(lever_id)
  if mapped_candidates:
    return mapped_candidates
  return _normalize_realism_lever_ids(record.get("next_required_lever_ids"))


def _lever_allowed_mapped_repair_targets(
  deterministic_numeric_guidance: Optional[Dict[str, Any]],
) -> Dict[str, List[Dict[str, Any]]]:
  guidance = deterministic_numeric_guidance if isinstance(deterministic_numeric_guidance, dict) else {}
  mapping_quarters: Dict[Tuple[str, str, str], set[int]] = {}
  for issue_packet in (guidance.get("issue_repair_packets") or []):
    if not isinstance(issue_packet, dict):
      continue
    issue_code = str(issue_packet.get("issue_code") or "").strip().lower()
    if not issue_code:
      continue
    for repair_target in (issue_packet.get("repair_targets") or []):
      if not isinstance(repair_target, dict):
        continue
      quarter = int(_safe_float(repair_target.get("quarter")) or 0)
      if quarter < 1:
        continue
      for driver_path in (repair_target.get("driver_paths") or []):
        if not isinstance(driver_path, dict):
          continue
        lever_id = str(driver_path.get("lever") or "").strip()
        if not lever_id:
          continue
        target_metric_name = post_intake_direct_target_metric_for_lever(lever_id)
        if not target_metric_name:
          continue
        mapping_quarters.setdefault((lever_id, issue_code, target_metric_name), set()).add(quarter)
  lever_mapping_map: Dict[str, List[Dict[str, Any]]] = {}
  for lever_id, issue_code, target_metric_name in sorted(mapping_quarters.keys()):
    lever_mapping_map.setdefault(lever_id, []).append(
      {
        "issue_code": issue_code,
        "target_metric_name": target_metric_name,
        "target_quarters": sorted(mapping_quarters[(lever_id, issue_code, target_metric_name)]),
      }
    )
  return lever_mapping_map


def _unified_declared_repair_mapping_contract_error(
  *,
  lever_adjustments: Optional[List[Dict[str, Any]]],
  primary_target_metric_names: Optional[List[str]],
  targets_by_quarter: Optional[List[Dict[str, Any]]],
  deterministic_numeric_guidance: Optional[Dict[str, Any]],
) -> Optional[str]:
  guidance = deterministic_numeric_guidance if isinstance(deterministic_numeric_guidance, dict) else {}
  issue_packet_map = {
    str(item.get("issue_code") or "").strip().lower(): copy.deepcopy(item)
    for item in (guidance.get("issue_repair_packets") or [])
    if isinstance(item, dict) and str(item.get("issue_code") or "").strip()
  }
  primary_metric_set = {
    str(metric or "").strip().lower()
    for metric in (primary_target_metric_names or [])
    if str(metric or "").strip()
  }
  target_metric_quarters: Dict[str, set[int]] = {}
  for item in (targets_by_quarter or []):
    if not isinstance(item, dict):
      continue
    quarter_index = int(_safe_float(item.get("quarter_index")) or 0)
    if quarter_index < 1:
      continue
    for metric_name in primary_metric_set:
      if _safe_float(item.get(metric_name)) is not None:
        target_metric_quarters.setdefault(metric_name, set()).add(quarter_index)
  for adjustment in (lever_adjustments or []):
    if not isinstance(adjustment, dict):
      continue
    lever_id = str(adjustment.get("lever_id") or "").strip()
    if not lever_id:
      continue
    mapped_targets = _normalize_unified_mapped_repair_targets(
      adjustment.get("mapped_repair_targets") or []
    )
    if not mapped_targets:
      return (
        f"{lever_id} must include non-empty mapped_repair_targets with explicit "
        "issue_code, target_metric_name, and target_quarters."
      )
    for mapping in mapped_targets:
      issue_code = str(mapping.get("issue_code") or "").strip().lower()
      target_metric_name = str(mapping.get("target_metric_name") or "").strip().lower()
      target_quarters = [
        int(_safe_float(quarter) or 0)
        for quarter in (mapping.get("target_quarters") or [])
        if int(_safe_float(quarter) or 0) >= 1
      ]
      if target_metric_name not in primary_metric_set:
        return (
          f"{lever_id} mapped target metric {target_metric_name or 'missing'} must appear in "
          "primary_target_metric_names."
        )
      declared_metric_quarters = set(target_metric_quarters.get(target_metric_name) or set())
      if not declared_metric_quarters.issuperset(set(target_quarters)):
        return (
          f"{lever_id} mapped target quarters {sorted(target_quarters)} for {target_metric_name} must be "
          "covered in targets_by_quarter."
        )
      issue_packet = issue_packet_map.get(issue_code)
      if not isinstance(issue_packet, dict) or not issue_packet:
        return f"{lever_id} mapped issue_code {issue_code or 'missing'} is not present in deterministic issue repair packets."
      matched_paths, covered_quarters = _declared_mapping_driver_paths_for_lever(
        issue_packet=issue_packet,
        lever_id=lever_id,
        target_metric_name=target_metric_name,
        target_quarters=target_quarters,
      )
      if not matched_paths:
        return (
          f"{lever_id} has no deterministic driver path for mapped issue {issue_code}, "
          f"target metric {target_metric_name}, quarters {sorted(target_quarters)}."
        )
      if set(covered_quarters) != set(target_quarters):
        return (
          f"{lever_id} mapped quarters {sorted(target_quarters)} are not fully covered by deterministic "
          f"driver paths for issue {issue_code} and target metric {target_metric_name}. "
          f"covered={sorted(covered_quarters)}."
        )
  return None


def _numeric_decision_contract_error(
  *,
  parsed: Optional[Dict[str, Any]],
  action_quarter_mode: str,
  required_target_quarters: Optional[List[int]] = None,
) -> Optional[str]:
  decision = parsed if isinstance(parsed, dict) else {}
  recommendation_mode = str(decision.get("recommendation_mode") or "").strip().lower()
  recommended_actions = [item for item in (decision.get("recommended_actions") or []) if isinstance(item, dict)]
  if recommendation_mode not in {"maintain", "adjust"}:
    return "recommendation_mode must be either 'maintain' or 'adjust'."
  if recommendation_mode == "maintain":
    if recommended_actions:
      return "recommendation_mode='maintain' must not include recommended_actions."
    return None
  return _numeric_adjust_actions_contract_error(
    recommended_actions=recommended_actions,
    action_quarter_mode=action_quarter_mode,
    require_issue_codes=False,
    required_target_quarters=required_target_quarters,
  )


def _unified_convergence_decision_contract_error(
  *,
  parsed: Optional[Dict[str, Any]],
  required_target_quarters: Optional[List[int]] = None,
  numeric_solver_contract: Optional[Dict[str, Any]] = None,
  deterministic_numeric_guidance: Optional[Dict[str, Any]] = None,
  controller_retry_context: Optional[Dict[str, Any]] = None,
  baseline_map: Optional[Dict[str, List[float]]] = None,
  full_horizon_quarter_count: Optional[int] = None,
) -> Optional[str]:
  decision = parsed if isinstance(parsed, dict) else {}
  retry_context = controller_retry_context if isinstance(controller_retry_context, dict) else {}
  writable_catalog = (
    (numeric_solver_contract or {}).get("writable_lever_catalog")
    if isinstance((numeric_solver_contract or {}).get("writable_lever_catalog"), dict)
    else {}
  )
  lever_value_kind_by_id: Dict[str, str] = {}
  for entry in (writable_catalog.get("entries") or []):
    if not isinstance(entry, dict):
      continue
    lever_id = str(entry.get("lever_id") or "").strip()
    if not lever_id:
      continue
    lever_value_kind_by_id[lever_id] = str(
      entry.get("value_kind")
      or entry.get("value_type")
      or entry.get("input_semantics")
      or ""
    ).strip().lower()
  strategy_class = str(decision.get("strategy_class") or "").strip()
  if not strategy_class:
    return "strategy_class is required for unified convergence."
  change_type = str(decision.get("change_type") or "").strip().lower()
  if not change_type:
    return "change_type is required for unified convergence."
  progress_expectation = str(decision.get("progress_expectation") or "").strip().lower()
  if not progress_expectation:
    return "progress_expectation is required for unified convergence."
  strategy_rationale = str(decision.get("strategy_rationale") or "").strip()
  if not strategy_rationale:
    return "strategy_rationale is required for unified convergence."
  lever_selection = [
    str(item or "").strip()
    for item in (decision.get("lever_selection") or [])
    if str(item or "").strip()
  ]
  if not lever_selection:
    return "lever_selection must include at least one authorized writable lever id."
  unmapped_lever_selection = [
    lever_id
    for lever_id in lever_selection
    if not post_intake_driver_target_mapping_entry(lever_id)
  ]
  if unmapped_lever_selection:
    return (
      "lever_selection contains lever ids with no direct driver-target mapping table entry: "
      f"{unmapped_lever_selection}."
    )
  lever_adjustments = [
    item for item in (decision.get("lever_adjustments") or [])
    if isinstance(item, dict)
  ]
  lever_selection_set = set(lever_selection)
  explicit_adjustment_lever_ids: set[str] = set()
  for adjustment in lever_adjustments:
    lever_id = str(adjustment.get("lever_id") or "").strip()
    if not lever_id:
      return "lever_adjustments contained an entry with missing lever_id."
    if not post_intake_driver_target_mapping_entry(lever_id):
      return f"{lever_id} has no direct driver-target mapping table entry."
    if lever_id not in lever_selection_set:
      return f"lever_adjustments contained lever_id {lever_id} which was not declared in lever_selection."
    explicit_adjustment_lever_ids.add(lever_id)
    value_mode = str(adjustment.get("value_mode") or "").strip().lower()
    if value_mode not in {"exact", "band"}:
      return f"{lever_id} has unsupported value_mode {value_mode or 'missing'}."
    has_shape_trajectory = bool(_shape_sensitive_trajectory_values_by_quarter(adjustment))
    if not has_shape_trajectory and value_mode == "exact" and _safe_float(adjustment.get("exact_value")) is None:
      return f"{lever_id} exact mode requires exact_value."
    if not has_shape_trajectory and value_mode == "band" and (
      _safe_float(adjustment.get("min_value")) is None
      or _safe_float(adjustment.get("max_value")) is None
    ):
      return f"{lever_id} band mode requires min_value and max_value."
    if adjustment and not _normalize_unified_mapped_repair_targets(
      adjustment.get("mapped_repair_targets") or []
    ):
      return (
        f"{lever_id} must include mapped_repair_targets that explicitly name the issue, "
        "target metric, and target quarters this lever is intended to move."
      )
    value_kind = str(lever_value_kind_by_id.get(lever_id) or "").strip().lower()
    ratio_like_value = value_kind in {"ratio", "percent", "percent_of_revenue", "margin"}
    integer_like_value = value_kind in {"currency", "quarter_currency", "day_count", "count", "integer"}
    if not has_shape_trajectory and value_mode == "exact":
      exact_value = float(_safe_float(adjustment.get("exact_value")) or 0.0)
      if ratio_like_value and round(exact_value, 2) != exact_value:
        return f"{lever_id} exact_value must use at most 2 decimal places for ratio-like levers. received={exact_value}."
      if integer_like_value and float(int(round(exact_value))) != exact_value:
        return f"{lever_id} exact_value must be a whole-dollar or whole-count integer. received={exact_value}."
    if not has_shape_trajectory and value_mode == "band":
      band_min = float(_safe_float(adjustment.get("min_value")) or 0.0)
      band_max = float(_safe_float(adjustment.get("max_value")) or 0.0)
      if ratio_like_value and (round(band_min, 2) != band_min or round(band_max, 2) != band_max):
        return f"{lever_id} min_value/max_value must use at most 2 decimal places for ratio-like levers. received=[{band_min}, {band_max}]."
      if integer_like_value and (
        float(int(round(band_min))) != band_min or float(int(round(band_max))) != band_max
      ):
        return f"{lever_id} min_value/max_value must be whole-dollar or whole-count integers. received=[{band_min}, {band_max}]."
  missing_explicit_adjustment_lever_ids = [
    lever_id
    for lever_id in lever_selection
    if lever_id not in explicit_adjustment_lever_ids
  ]
  if missing_explicit_adjustment_lever_ids:
    return (
      "Every selected lever must include an explicit lever_adjustment. Missing adjustments for: "
      f"{missing_explicit_adjustment_lever_ids}."
    )
  primary_target_metric_names = _unified_required_target_metric_keys(
    decision_payload=decision,
    numeric_solver_contract=numeric_solver_contract,
  )
  if len(primary_target_metric_names) < _UNIFIED_PRIMARY_TARGET_MIN_COUNT:
    return (
      f"primary_target_metric_names must include at least {_UNIFIED_PRIMARY_TARGET_MIN_COUNT} "
      "authorized metric ids."
    )
  if len(primary_target_metric_names) > _UNIFIED_PRIMARY_TARGET_MAX_COUNT:
    return (
      f"primary_target_metric_names must include no more than {_UNIFIED_PRIMARY_TARGET_MAX_COUNT} "
      "authorized metric ids."
    )
  for tolerance in [item for item in (decision.get("target_tolerances") or []) if isinstance(item, dict)]:
    metric_name = str(tolerance.get("metric_name") or "").strip().lower() or "unknown"
    relative_tolerance_pct = _safe_float(tolerance.get("relative_tolerance_pct"))
    absolute_tolerance = _safe_float(tolerance.get("absolute_tolerance"))
    if relative_tolerance_pct is not None and round(float(relative_tolerance_pct), 2) != float(relative_tolerance_pct):
      return (
        f"target_tolerances metric {metric_name} relative_tolerance_pct must use at most 2 decimal places. "
        f"received={relative_tolerance_pct}."
      )
    if absolute_tolerance is not None and float(int(round(float(absolute_tolerance)))) != float(absolute_tolerance):
      return (
        f"target_tolerances metric {metric_name} absolute_tolerance must be a whole-dollar integer. "
        f"received={absolute_tolerance}."
      )
  normalized_tolerances = _merge_required_target_tolerances(
    decision.get("target_tolerances") or [],
    primary_target_metric_names,
  )
  targets_by_quarter = _augment_solver_quarter_target_metrics(
    raw_targets=decision.get("targets_by_quarter"),
    required_metric_names=primary_target_metric_names,
    numeric_solver_contract=copy.deepcopy(numeric_solver_contract),
    required_target_quarters=copy.deepcopy(required_target_quarters),
  )
  if not targets_by_quarter:
    return "targets_by_quarter must include numeric quarter targets for the current cycle."
  mapping_contract_error = _unified_declared_repair_mapping_contract_error(
    lever_adjustments=copy.deepcopy(lever_adjustments),
    primary_target_metric_names=copy.deepcopy(primary_target_metric_names),
    targets_by_quarter=copy.deepcopy(targets_by_quarter),
    deterministic_numeric_guidance=copy.deepcopy(
      deterministic_numeric_guidance if isinstance(deterministic_numeric_guidance, dict) else {}
    ),
  )
  if mapping_contract_error:
    return mapping_contract_error
  target_quarters = sorted(
    {
      int(_safe_float(item.get("quarter_index")) or 0)
      for item in targets_by_quarter
      if int(_safe_float(item.get("quarter_index")) or 0) >= 1
    }
  )
  shape_sensitive_requirements = _shape_sensitive_remaining_horizon_requirements(
    selected_lever_ids=copy.deepcopy(lever_selection),
    targeted_quarters=copy.deepcopy(target_quarters or required_target_quarters or []),
    numeric_solver_contract=copy.deepcopy(numeric_solver_contract),
    lever_adjustments=copy.deepcopy(lever_adjustments),
    baseline_map=copy.deepcopy(baseline_map),
    full_horizon_quarter_count=full_horizon_quarter_count,
  )
  if shape_sensitive_requirements.get("required_lever_ids"):
    adjustment_map = {
      str(item.get("lever_id") or "").strip(): copy.deepcopy(item)
      for item in lever_adjustments
      if isinstance(item, dict) and str(item.get("lever_id") or "").strip()
    }
    required_shape_quarters = copy.deepcopy(
      shape_sensitive_requirements.get("required_target_quarters") or []
    )
    for lever_id in (shape_sensitive_requirements.get("required_lever_ids") or []):
      if lever_id not in adjustment_map:
        return (
          f"{lever_id} is shape-sensitive and requires an explicit lever_adjustment with full values or trajectory_values."
        )
      path_error = _shape_sensitive_path_validation_error(
        lever_id=lever_id,
        adjustment=adjustment_map.get(lever_id),
        required_target_quarters=required_shape_quarters,
      )
      if path_error:
        return path_error
  effective_required_target_quarters = sorted(
    {
      int(_safe_float(item) or 0)
      for item in (required_target_quarters or [])
      if int(_safe_float(item) or 0) >= 1
    }
  )
  synthetic_action = {
    "action_id": "unified_cycle",
    "target_quarters": target_quarters,
    "solver_allowed_lever_ids": lever_selection,
    "required_target_metric_keys": copy.deepcopy(primary_target_metric_names),
    "quarter_target_metrics": targets_by_quarter,
  }
  numeric_contract_error = _numeric_adjust_actions_contract_error(
    recommended_actions=[synthetic_action],
    action_quarter_mode="target_quarters",
    require_issue_codes=False,
    required_target_quarters=effective_required_target_quarters,
    default_required_metric_keys=copy.deepcopy(primary_target_metric_names),
  )
  if numeric_contract_error:
    return numeric_contract_error
  previous_lever_set = {
    str(item or "").strip()
    for item in (
      retry_context.get("previous_levers_used")
      or retry_context.get("previous_allowed_lever_ids")
      or []
    )
    if str(item or "").strip()
  }
  required_new_levers = int(_safe_float(retry_context.get("required_new_levers")) or 0)
  if required_new_levers > 0:
    new_lever_count = len([lever_id for lever_id in lever_selection if lever_id not in previous_lever_set])
    if new_lever_count < required_new_levers:
      return (
        "Escalation requires a materially expanded lever mix for this cycle. "
        f"Need at least {required_new_levers} newly introduced levers; got {new_lever_count}."
      )
  selected_families = {
    str(lever_id.split("::", 1)[0] or "").strip().lower()
    for lever_id in lever_selection
    if str(lever_id).strip()
  }
  declared_issue_metric_coverage: Dict[str, set[str]] = {}
  declared_issue_family_coverage: Dict[str, set[str]] = {}
  declared_issue_quarter_coverage: Dict[str, set[int]] = {}
  for adjustment in lever_adjustments:
    if not isinstance(adjustment, dict):
      continue
    lever_id = str(adjustment.get("lever_id") or "").strip()
    if not lever_id:
      continue
    lever_family = _lever_family_from_lever_id(lever_id)
    for mapping in _normalize_unified_mapped_repair_targets(
      adjustment.get("mapped_repair_targets") or []
    ):
      issue_code = str(mapping.get("issue_code") or "").strip().lower()
      metric_name = str(mapping.get("target_metric_name") or "").strip().lower()
      if not issue_code:
        continue
      if metric_name:
        declared_issue_metric_coverage.setdefault(issue_code, set()).add(metric_name)
      if lever_family:
        declared_issue_family_coverage.setdefault(issue_code, set()).add(lever_family)
      for quarter_index in (
        int(_safe_float(item) or 0)
        for item in (mapping.get("target_quarters") or [])
      ):
        if quarter_index >= 1:
          declared_issue_quarter_coverage.setdefault(issue_code, set()).add(int(quarter_index))
  required_lever_families = {
    str(item or "").strip().lower()
    for item in (retry_context.get("required_lever_families") or [])
    if str(item or "").strip()
  }
  missing_families = sorted(family for family in required_lever_families if family not in selected_families)
  if missing_families:
    return (
      "Escalation requires direct coverage from the mandated lever families. "
      f"Missing families: {missing_families}."
    )
  for requirement in [item for item in (retry_context.get("issue_coverage_requirements") or []) if isinstance(item, dict)]:
    issue_code = str(requirement.get("issue_code") or "").strip().lower()
    metric_candidates = {
      str(item or "").strip().lower()
      for item in (requirement.get("metric_candidates") or [])
      if str(item or "").strip()
    }
    if metric_candidates and not any(metric_name in metric_candidates for metric_name in primary_target_metric_names):
      return (
        "Escalation requires direct target coverage for each open issue. "
        f"Issue {str(requirement.get('issue_code') or '').strip() or 'unknown'} has no covered primary metric."
      )
    if metric_candidates and not (declared_issue_metric_coverage.get(issue_code) or set()) & metric_candidates:
      return (
        "Escalation requires each open issue to have a declared mapped repair target, not just broad metric overlap. "
        f"Issue {str(requirement.get('issue_code') or '').strip() or 'unknown'} has no mapped lever adjustment covering {sorted(metric_candidates)}."
      )
    issue_required_families = {
      str(item or "").strip().lower()
      for item in (requirement.get("required_lever_families") or [])
      if str(item or "").strip()
    }
    missing_issue_families = sorted(
      family
      for family in issue_required_families
      if family not in selected_families
    )
    if missing_issue_families:
      return (
        "Escalation requires each open issue to be attacked with the full declared lever-family set. "
        f"Issue {str(requirement.get('issue_code') or '').strip() or 'unknown'} is missing families {missing_issue_families}."
      )
    missing_declared_issue_families = sorted(
      family
      for family in issue_required_families
      if family not in (declared_issue_family_coverage.get(issue_code) or set())
    )
    if missing_declared_issue_families:
      return (
        "Escalation requires each open issue to have declared mapped lever-family coverage across the full required set. "
        f"Issue {str(requirement.get('issue_code') or '').strip() or 'unknown'} is missing declared mapped families {missing_declared_issue_families}."
      )
    relevant_quarters = {
      int(_safe_float(item) or 0)
      for item in (
        requirement.get("affected_quarters")
        or requirement.get("relevant_quarters")
        or []
      )
      if int(_safe_float(item) or 0) >= 1
    }
    if relevant_quarters and not ((declared_issue_quarter_coverage.get(issue_code) or set()) & relevant_quarters):
      return (
        "Escalation requires declared mapped repair targets to cover the issue's active quarters. "
        f"Issue {str(requirement.get('issue_code') or '').strip() or 'unknown'} has no mapped quarter overlap with {sorted(relevant_quarters)}."
      )
  return None

def _final_stabilizer_decision_contract_error(
  *,
  parsed: Optional[Dict[str, Any]],
  final_stabilizer_context: Optional[Dict[str, Any]],
  controller_retry_context: Optional[Dict[str, Any]],
) -> Optional[str]:
  decision = parsed if isinstance(parsed, dict) else {}
  context = final_stabilizer_context if isinstance(final_stabilizer_context, dict) else {}
  retry_context = controller_retry_context if isinstance(controller_retry_context, dict) else {}
  recommendation_mode = str(decision.get("recommendation_mode") or "").strip().lower()
  trigger_assessment = (
    context.get("stabilization_trigger_assessment")
    if isinstance(context.get("stabilization_trigger_assessment"), dict)
    else {}
  )
  guarantee_policy = (
    context.get("full_run_guarantee_policy")
    if isinstance(context.get("full_run_guarantee_policy"), dict)
    else {}
  )
  guarantee_stall = (
    context.get("guarantee_stall_assessment")
    if isinstance(context.get("guarantee_stall_assessment"), dict)
    else {}
  )
  review_role = str(context.get("review_role") or "").strip().lower()
  required_adjust = bool(trigger_assessment.get("needs_stabilization"))
  if recommendation_mode == "maintain" and required_adjust:
    if review_role == "mandatory_full_run_viability_guarantee" or bool(guarantee_policy.get("terminal_convergence_loop")):
      return (
        "Terminal final guarantee still requires stabilization, so recommendation_mode must be 'adjust', "
        "not 'maintain'."
      )
    return "Stabilization is still required, so recommendation_mode must be 'adjust'."
  recommended_actions = [
    item for item in (decision.get("recommended_actions") or []) if isinstance(item, dict)
  ]
  if bool(guarantee_stall.get("stalled")) and recommendation_mode != "adjust":
    return "Final guarantee stall detected; the next attempt must materially change tactic with recommendation_mode='adjust'."
  if recommendation_mode == "adjust" and bool(guarantee_stall.get("stalled")):
    previous_allowed = {
      str(item).strip()
      for item in (retry_context.get("previous_allowed_lever_ids") or [])
      if str(item).strip()
    }
    all_writable_allowed = {
      str(item).strip()
      for item in (retry_context.get("all_writable_lever_ids") or [])
      if str(item).strip()
    }
    current_allowed = {
      str(item).strip()
      for action in recommended_actions
      for item in (action.get("solver_allowed_lever_ids") or [])
      if str(item).strip()
    }
    minimum_new_lever_count = max(1, int(_safe_float(guarantee_stall.get("minimum_new_lever_count")) or 0))
    current_targets: Dict[str, float] = {}
    for action in recommended_actions:
      for item in (action.get("quarter_target_metrics") or []):
        if not isinstance(item, dict):
          continue
        quarter_index = int(_safe_float(item.get("quarter_index")) or 0)
        if quarter_index < 1:
          continue
        for metric_name, raw_value in item.items():
          if str(metric_name or "").strip().lower() == "quarter_index":
            continue
          numeric_value = _safe_float(raw_value)
          if numeric_value is None:
            continue
          current_targets[f"q{quarter_index}:{str(metric_name or '').strip().lower()}"] = float(numeric_value)
    previous_target_key = str((retry_context.get("prior_target_keys") or [""])[-1] or "").strip()
    current_target_key = json.dumps(current_targets, sort_keys=True)
    materially_same_targets = bool(previous_target_key and current_target_key == previous_target_key)
    previous_already_full_scope = bool(all_writable_allowed) and previous_allowed == all_writable_allowed
    current_is_full_scope = bool(all_writable_allowed) and current_allowed == all_writable_allowed
    if current_allowed == previous_allowed and materially_same_targets:
      if previous_already_full_scope and current_is_full_scope:
        return (
          "Final guarantee stall detected; all writable levers were already in play, so the retry must materially "
          "reframe quarter targets or tactic rather than reusing the same full-scope target package."
        )
      return "Final guarantee stall detected; the retry reused the same lever set and target shape."
    if (
      materially_same_targets
      and not (previous_already_full_scope and current_is_full_scope)
      and len(current_allowed - previous_allowed) < minimum_new_lever_count
    ):
      return "Final guarantee stall detected; the retry must widen the lever mix materially before continuing."
  return None


def _realism_verification_failure_payload(
  *,
  prompt_file: str,
  status: str,
  detail: str = "",
) -> Dict[str, Any]:
  return {
    "contract_version": "realism_resolution_verification_v1",
    "status": status,
    "prompt_file": prompt_file,
    "verification_status": "not_completed",
    "detail": str(detail or "").strip(),
    "verification": {},
  }


def _target_miss_verification_fallback(
  *,
  phase: str,
  reason: str,
  last_verification: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
  fallback = (
    copy.deepcopy(last_verification)
    if isinstance(last_verification, dict) and last_verification
    else _realism_verification_failure_payload(
      prompt_file="client_intake_and_finmo/prompts/realism_resolution/verifier.md",
      status="skipped_infeasible_target_miss",
      detail=str(reason or "").strip(),
    )
  )
  if not isinstance(fallback, dict):
    fallback = _realism_verification_failure_payload(
      prompt_file="client_intake_and_finmo/prompts/realism_resolution/verifier.md",
      status="skipped_infeasible_target_miss",
      detail=str(reason or "").strip(),
    )
  fallback["target_verification_gate"] = {
    "controller_state": "infeasible",
    "phase": str(phase or "").strip() or "unknown",
    "reason": str(reason or "").strip() or "Target verification could not proceed because the numeric pass exhausted its retry budget.",
  }
  return fallback


def _run_realism_resolution_openai(
  *,
  draft_id: str,
  business_facts: Dict[str, Any],
  ops_json: Dict[str, Any],
  financials_json: Dict[str, Any],
  planning_mode: str,
  planning_mode_reason: str,
  planning_mode_prompt_file: str,
  planner_issue_state: Dict[str, Any],
  solved_model_input_json: Dict[str, Any],
  solved_finmo_json: Dict[str, Any],
  prior_numeric_feedback: Optional[Dict[str, Any]] = None,
  controller_retry_context: Optional[Dict[str, Any]] = None,
  current_iteration: int = 1,
) -> Dict[str, Any]:
  try:
    from client_intake_and_finmo.numeric_execution import build_numeric_solver_contract  # type: ignore
  except Exception:
    from numeric_execution import build_numeric_solver_contract  # type: ignore
  prompt_file = "client_intake_and_finmo/prompts/realism_resolution/reviewer.md"
  planner_issue_state = (
    copy.deepcopy(planner_issue_state)
    if isinstance(planner_issue_state, dict)
    else {}
  )
  active_issue_codes = _active_issue_codes_from_planner_issue_state(planner_issue_state)
  if not active_issue_codes:
    return _realism_resolution_failure_payload(
      prompt_file=prompt_file,
      status="skipped_no_realism_issues",
      detail="No realism issues were active before the resolution pass.",
    )
  api_key = _openai_key()
  if not api_key:
    return _realism_resolution_failure_payload(
      prompt_file=prompt_file,
      status="skipped_missing_openai_key",
      detail="OPENAI_API_KEY is not configured.",
    )

  lever_catalog = _build_writable_lever_review_catalog(solved_model_input_json)
  allowed_lever_ids = [str(item.get("lever_id") or "").strip() for item in lever_catalog if str(item.get("lever_id") or "").strip()]
  if not allowed_lever_ids:
    return _realism_resolution_failure_payload(
      prompt_file=prompt_file,
      status="failed_missing_levers",
      detail="No writable lever ids were available for realism resolution.",
    )
  full_numeric_solver_contract = build_numeric_solver_contract(
    planning_mode=planning_mode,
    planning_mode_reason=planning_mode_reason,
    selected_cash_strategy=_resolved_cash_strategy(financials_json),
    issue_status_records=copy.deepcopy((planner_issue_state or {}).get("issue_status_records") or []),
    writable_lever_catalog=copy.deepcopy(lever_catalog),
    current_model_input_json=copy.deepcopy(solved_model_input_json or {}),
    current_finmo_json=copy.deepcopy(solved_finmo_json or {}),
    pass_name="realism_resolution",
    contract_scope="planner",
  )
  retry_scope_payload = _build_retry_scope_payload(
    controller_retry_context=copy.deepcopy(controller_retry_context or {}),
    prior_numeric_feedback=copy.deepcopy(prior_numeric_feedback or {}),
    numeric_solver_contract=copy.deepcopy(full_numeric_solver_contract),
    deterministic_numeric_guidance=None,
    solved_model_input_json=copy.deepcopy(solved_model_input_json or {}),
    solved_finmo_json=copy.deepcopy(solved_finmo_json or {}),
  )
  scoped_numeric_solver_contract = _subset_numeric_solver_contract(
    numeric_solver_contract=copy.deepcopy(full_numeric_solver_contract),
    retry_scope_payload=copy.deepcopy(retry_scope_payload),
  )
  scoped_lever_catalog = copy.deepcopy(retry_scope_payload.get("lever_catalog_entries") or lever_catalog)
  scoped_lever_values = copy.deepcopy(
    retry_scope_payload.get("lever_current_values") or _solved_lever_value_map(solved_model_input_json)
  )
  scoped_model_payload = copy.deepcopy(retry_scope_payload.get("model_input_payload") or solved_model_input_json)
  scoped_finmo_rows = copy.deepcopy(
    retry_scope_payload.get("finmo_quarter_rows")
    or [row for row in ((solved_finmo_json or {}).get("quarter_rows") or []) if isinstance(row, dict)]
  )
  required_target_quarters = _relevant_solver_target_quarters(scoped_numeric_solver_contract)
  required_quarter_target_scaffold = _solver_required_quarter_target_scaffold(
    copy.deepcopy(scoped_numeric_solver_contract),
    required_target_quarters=copy.deepcopy(required_target_quarters),
  )
  deterministic_issue_packets = _build_deterministic_issue_packets(
    issue_status_records=copy.deepcopy((planner_issue_state or {}).get("issue_status_records") or []),
    numeric_solver_contract=copy.deepcopy(scoped_numeric_solver_contract),
  )
  prompt_safe_planner_issue_state = {
    "issue_status_records": copy.deepcopy((planner_issue_state or {}).get("issue_status_records") or []),
    "detected_issue_count": int(_safe_float((planner_issue_state or {}).get("detected_issue_count")) or 0),
    "remaining_issue_count": int(_safe_float((planner_issue_state or {}).get("remaining_issue_count")) or 0),
    "resolved_issue_count": int(_safe_float((planner_issue_state or {}).get("resolved_issue_count")) or 0),
    "iteration_pending_issue_count": int(_safe_float((planner_issue_state or {}).get("iteration_pending_issue_count")) or 0),
  }

  system_prompt = _load_realism_resolution_prompt()
  user_context = {
    "draft_id": str(draft_id or "").strip(),
    "current_iteration": int(current_iteration or 1),
    "business_name": str((business_facts or {}).get("name") or (business_facts or {}).get("business_name") or "").strip(),
    "required_numeric_resolution_contract": _unified_solver_target_contract_spec_payload(),
    "planning_mode_context": _build_planning_mode_context(
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=planning_mode_prompt_file,
    ),
    "ops_milestones": _build_realism_milestone_context(
      ops_json=ops_json,
      solved_model_input_json=solved_model_input_json,
    ),
    "planner_issue_state": prompt_safe_planner_issue_state,
    "prior_numeric_solver_feedback": copy.deepcopy(prior_numeric_feedback or {}),
    "controller_retry_context": copy.deepcopy(controller_retry_context or {}),
    "retry_scope_payload": copy.deepcopy(retry_scope_payload),
    "required_target_quarters": copy.deepcopy(required_target_quarters),
    "required_quarter_target_scaffold": copy.deepcopy(required_quarter_target_scaffold),
    "deterministic_issue_packets": copy.deepcopy(deterministic_issue_packets),
    "numeric_solver_contract": copy.deepcopy(scoped_numeric_solver_contract),
    "writable_lever_catalog": copy.deepcopy(scoped_lever_catalog),
    "writable_lever_current_values": copy.deepcopy(scoped_lever_values),
    "solved_model_input_json": copy.deepcopy(scoped_model_payload),
    "solved_finmo_quarter_rows": copy.deepcopy(scoped_finmo_rows),
  }
  payload = {
    "model": _openai_model(),
    "temperature": 0,
    "input": [
      {"role": "system", "content": [{"type": "input_text", "text": system_prompt}]},
      {"role": "user", "content": [{"type": "input_text", "text": json.dumps(user_context, ensure_ascii=False)}]},
    ],
    "text": {
      "format": {
        "type": "json_schema",
        "name": "realism_resolution_decision",
        "schema": _realism_resolution_schema(allowed_lever_ids),
        "strict": True,
      }
    },
  }
  try:
    resp = _post_openai(
      url="https://api.openai.com/v1/responses",
      headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
      payload=payload,
    )
  except Exception as exc:
    return _realism_resolution_failure_payload(
      prompt_file=prompt_file,
      status="failed_openai_request",
      detail=str(exc),
    )
  if resp.status_code >= 400:
    return _realism_resolution_failure_payload(
      prompt_file=prompt_file,
      status="failed_openai_status",
      detail=resp.text[:1200],
    )
  parsed = _parse_responses_json_dict(resp.json())
  if not isinstance(parsed, dict):
    return _realism_resolution_failure_payload(
      prompt_file=prompt_file,
      status="failed_parse",
      detail="Unable to parse realism resolution JSON.",
    )
  contract_error = _realism_resolution_decision_contract_error(
    parsed=parsed,
    active_issue_codes=active_issue_codes,
    required_target_quarters=copy.deepcopy(required_target_quarters),
  )
  if contract_error:
    retry_payload = copy.deepcopy(payload)
    retry_payload["input"] = list(retry_payload.get("input") or []) + [
      {
        "role": "user",
        "content": [
          {
            "type": "input_text",
            "text": json.dumps(
              {
                "repair_contract_violation": contract_error,
                "required_active_issue_codes": active_issue_codes,
                "required_target_quarters": copy.deepcopy(required_target_quarters),
                "required_quarter_target_scaffold": copy.deepcopy(required_quarter_target_scaffold),
                "instruction": (
                  "You must return recommendation_mode='adjust' and at least one recommended_action because "
                  "active realism issues are still open in this pass. Python already owns deterministic issue packets, "
                  "severity, quarter scope, and eligible lever space for this pass. "
                  "quarter_target_metrics must cover every required_target_quarter. "
                  "Use required_quarter_target_scaffold as the exact quarter-by-quarter target structure to fill and adjust."
                ),
              },
              ensure_ascii=False,
            ),
          }
        ],
      }
    ]
    try:
      retry_resp = _post_openai(
        url="https://api.openai.com/v1/responses",
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        payload=retry_payload,
      )
    except Exception as exc:
      return _realism_resolution_failure_payload(
        prompt_file=prompt_file,
        status="failed_contract_retry_request",
        detail=f"{contract_error} Retry error: {exc}",
      )
    if retry_resp.status_code >= 400:
      return _realism_resolution_failure_payload(
        prompt_file=prompt_file,
        status="failed_contract_retry_status",
        detail=f"{contract_error} Retry status body: {retry_resp.text[:1200]}",
      )
    parsed_retry = _parse_responses_json_dict(retry_resp.json())
    if not isinstance(parsed_retry, dict):
      return _realism_resolution_failure_payload(
        prompt_file=prompt_file,
        status="failed_contract_retry_parse",
        detail=f"{contract_error} Retry parse failed.",
      )
    retry_contract_error = _realism_resolution_decision_contract_error(
      parsed=parsed_retry,
      active_issue_codes=active_issue_codes,
      required_target_quarters=copy.deepcopy(required_target_quarters),
    )
    if retry_contract_error:
      return _realism_resolution_failure_payload(
        prompt_file=prompt_file,
        status="failed_invalid_repair_contract",
        detail=retry_contract_error,
      )
    parsed = parsed_retry
  return {
    "contract_version": "realism_resolution_decision_v1",
    "numeric_resolution_contract": _solver_target_contract_spec_payload(),
    "numeric_solver_contract": copy.deepcopy(scoped_numeric_solver_contract),
    "retry_scope_payload": copy.deepcopy(retry_scope_payload),
    "status": "completed",
    "prompt_file": prompt_file,
    "review_status": "completed",
    "detail": "",
    "deterministic_issue_packets": copy.deepcopy(deterministic_issue_packets),
    "decision": parsed,
  }


def _realism_verification_scope_payload(
  *,
  strategy_recheck_context: Optional[Dict[str, Any]],
  realism_pass_consistency_context: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
  if isinstance(strategy_recheck_context, dict) and strategy_recheck_context:
    mode = "strategy_recheck_full_realism"
  elif isinstance(realism_pass_consistency_context, dict) and realism_pass_consistency_context:
    mode = "pass_exit_full_realism"
  else:
    mode = "final_full_realism"
  return {
    "mode": mode,
    "policy": {
      "in_pass_retries_use_local_target_hit_and_local_coherence_only": True,
      "full_realism_verification_only_at_pass_exit_or_final_guarantee": True,
    },
  }


def _run_realism_verification_openai(
  *,
  draft_id: str,
  business_facts: Dict[str, Any],
  ops_json: Dict[str, Any],
  planning_mode: str,
  planning_mode_reason: str,
  planning_mode_prompt_file: str,
  protected_resolved_issue_constraints: Optional[List[Dict[str, Any]]] = None,
  strategy_recheck_context: Optional[Dict[str, Any]] = None,
  realism_pass_consistency_context: Optional[Dict[str, Any]] = None,
  realism_memo_before_resolution: Dict[str, Any],
  realism_resolution_decision: Dict[str, Any],
  realism_resolution_plan: Dict[str, Any],
  realism_resolution_result: Dict[str, Any],
  updated_model_input_json: Dict[str, Any],
  updated_finmo_json: Dict[str, Any],
) -> Dict[str, Any]:
  prompt_file = "client_intake_and_finmo/prompts/realism_resolution/verifier.md"
  api_key = _openai_key()
  if not api_key:
    return _realism_verification_failure_payload(
      prompt_file=prompt_file,
      status="skipped_missing_openai_key",
      detail="OPENAI_API_KEY is not configured.",
    )

  decision_payload = (
    realism_resolution_decision.get("decision")
    if isinstance(realism_resolution_decision.get("decision"), dict)
    else {}
  )
  plan_issue_packets = (
    realism_resolution_plan.get("issue_packets")
    if isinstance(realism_resolution_plan.get("issue_packets"), list)
    else []
  )
  deterministic_issue_packets = (
    realism_resolution_decision.get("deterministic_issue_packets")
    if isinstance(realism_resolution_decision.get("deterministic_issue_packets"), list)
    else []
  )
  issue_packets = [
    item
    for item in (
      plan_issue_packets
      or deterministic_issue_packets
      or (decision_payload.get("issue_packets") or [])
    )
    if isinstance(item, dict)
  ]
  if not issue_packets:
    return _realism_verification_failure_payload(
      prompt_file=prompt_file,
      status="failed_missing_issue_packets",
      detail="No issue packets were available for realism verification.",
    )

  lever_catalog = _build_writable_lever_review_catalog(updated_model_input_json)
  allowed_lever_ids = [str(item.get("lever_id") or "").strip() for item in lever_catalog if str(item.get("lever_id") or "").strip()]
  if not allowed_lever_ids:
    return _realism_verification_failure_payload(
      prompt_file=prompt_file,
      status="failed_missing_levers",
      detail="No writable lever ids were available for realism verification.",
    )

  try:
    verify_prompt = (_REALISM_RESOLUTION_PROMPTS_DIR / "verifier.md").read_text(encoding="utf-8").strip()
  except Exception as exc:
    return _realism_verification_failure_payload(
      prompt_file=prompt_file,
      status="failed_load_prompt",
      detail=str(exc),
    )

  user_context = {
    "draft_id": str(draft_id or "").strip(),
    "business_name": str((business_facts or {}).get("name") or (business_facts or {}).get("business_name") or "").strip(),
    "required_numeric_resolution_contract": _unified_solver_target_contract_spec_payload(),
    "verification_scope": _realism_verification_scope_payload(
      strategy_recheck_context=strategy_recheck_context,
      realism_pass_consistency_context=realism_pass_consistency_context,
    ),
    "planning_mode_context": _build_planning_mode_context(
      planning_mode=planning_mode,
      planning_mode_reason=planning_mode_reason,
      prompt_file=planning_mode_prompt_file,
    ),
    "ops_milestones": _build_realism_milestone_context(
      ops_json=ops_json,
      solved_model_input_json=updated_model_input_json,
    ),
    "realism_memo_before_resolution": realism_memo_before_resolution,
    "issue_packets": issue_packets,
    "realism_resolution_plan": realism_resolution_plan,
    "applied_updates": [
      item for item in ((realism_resolution_result or {}).get("applied_updates") or []) if isinstance(item, dict)
    ],
    "updated_model_input_json": updated_model_input_json,
    "updated_finmo_quarter_rows": [
      row for row in ((updated_finmo_json or {}).get("quarter_rows") or []) if isinstance(row, dict)
    ],
    "protected_resolved_issue_constraints": [
      item for item in (protected_resolved_issue_constraints or []) if isinstance(item, dict)
    ],
    "strategy_recheck_context": copy.deepcopy(strategy_recheck_context or {}),
    "realism_pass_consistency_context": copy.deepcopy(realism_pass_consistency_context or {}),
    "writable_lever_catalog": lever_catalog,
  }
  payload = {
    "model": _openai_model(),
    "input": [
      {"role": "system", "content": [{"type": "input_text", "text": verify_prompt}]},
      {"role": "user", "content": [{"type": "input_text", "text": json.dumps(user_context, ensure_ascii=False)}]},
    ],
    "text": {
      "format": {
        "type": "json_schema",
        "name": "realism_resolution_verification",
        "schema": _realism_verification_schema(allowed_lever_ids),
        "strict": True,
      }
    },
  }
  try:
    resp = _post_openai(
      url="https://api.openai.com/v1/responses",
      headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
      payload=payload,
    )
  except Exception as exc:
    return _realism_verification_failure_payload(
      prompt_file=prompt_file,
      status="failed_openai_request",
      detail=str(exc),
    )
  if resp.status_code >= 400:
    return _realism_verification_failure_payload(
      prompt_file=prompt_file,
      status="failed_openai_status",
      detail=resp.text[:1200],
    )
  parsed = _parse_responses_json_dict(resp.json())
  if not isinstance(parsed, dict):
    return _realism_verification_failure_payload(
      prompt_file=prompt_file,
      status="failed_parse",
      detail="Unable to parse realism verification JSON.",
    )
  return {
    "contract_version": "realism_resolution_verification_v1",
    "status": "completed",
    "prompt_file": prompt_file,
    "verification_status": "completed",
    "detail": "",
    "verification": parsed,
  }


def _q0_anchor_plausibility_user_payload(
  *,
  draft_id: str,
  business_facts: Optional[Dict[str, Any]],
  ops_json: Optional[Dict[str, Any]],
  lever_id: str,
  lever_entry: Optional[Dict[str, Any]],
  q0_value: Any,
  finmo_q0_row: Optional[Dict[str, Any]],
  derived_metrics: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
  business = business_facts if isinstance(business_facts, dict) else {}
  ops = ops_json if isinstance(ops_json, dict) else {}
  entry = lever_entry if isinstance(lever_entry, dict) else {}
  q0_row = finmo_q0_row if isinstance(finmo_q0_row, dict) else {}
  revenue_q0 = float(_safe_float(q0_row.get("revenue")) or 0.0)
  gross_profit_q0 = float(_safe_float(q0_row.get("gross_profit")) or 0.0)
  ebitda_q0 = float(_safe_float(q0_row.get("ebitda")) or 0.0)
  operating_cash_flow_q0 = float(_safe_float(q0_row.get("operating_cash_flow")) or 0.0)
  total_liabilities_q0 = float(_safe_float(q0_row.get("total_liabilities")) or 0.0)
  total_equity_q0 = float(_safe_float(q0_row.get("total_equity")) or 0.0)
  payload_metrics = copy.deepcopy(derived_metrics or {})
  payload_metrics["revenue_q0"] = revenue_q0
  payload_metrics["gross_margin_pct_q0"] = _safe_divide(gross_profit_q0, revenue_q0)
  payload_metrics["ebitda_margin_pct_q0"] = _safe_divide(ebitda_q0, revenue_q0)
  payload_metrics["operating_cash_flow_margin_q0"] = _safe_divide(operating_cash_flow_q0, revenue_q0)
  payload_metrics["debt_to_equity_q0"] = (
    float(total_liabilities_q0 / max(total_equity_q0, 1.0))
    if total_equity_q0 > 0.0
    else None
  )
  business_type = str(ops.get("business_type") or "").strip()
  business_description_summary = str(
    ops.get("business_description_summary")
    or business.get("business_description_summary")
    or ""
  ).strip()
  unit_description = str(ops.get("unit_description") or "").strip()
  return {
    "draft_id": str(draft_id or "").strip(),
    "business_name": str(business.get("name") or business.get("business_name") or "").strip(),
    "business_type": business_type,
    "naics": str(ops.get("business_naics_6") or "").strip(),
    "naics_context": {
      "title_or_proxy": business_type or None,
      "business_description_summary": business_description_summary or None,
      "unit_description": unit_description or None,
    },
    "lever": str(lever_id or "").strip(),
    "lever_label": str(entry.get("label_path") or entry.get("driver") or entry.get("lever_id") or "").strip(),
    "lever_section": str(entry.get("section") or "").strip(),
    "input_semantics": str(entry.get("input_semantics") or "").strip(),
    "q0_value": _safe_float(q0_value),
    "q0_revenue": revenue_q0,
    "derived_metrics": payload_metrics,
  }


def _run_q0_anchor_plausibility_review_openai(
  *,
  draft_id: str,
  lever_id: str,
  anchor_context_hash: str,
  user_payload: Dict[str, Any],
) -> Dict[str, Any]:
  prompt_file = "client_intake_and_finmo/prompts/anchor_plausibility/reviewer.md"
  prompt_trace: Dict[str, Any] = {}
  api_key = _openai_key()
  if not api_key:
    return _anchor_plausibility_failure_payload(
      draft_id=draft_id,
      lever_id=lever_id,
      anchor_context_hash=anchor_context_hash,
      prompt_file=prompt_file,
      status="skipped_missing_openai_key",
      detail="OPENAI_API_KEY is not configured.",
      prompt_trace=prompt_trace,
    )
  system_prompt = _load_anchor_plausibility_prompt()
  prompt_trace = {
    "system_prompt": system_prompt,
    "user_payload": copy.deepcopy(user_payload),
  }
  payload = {
    "model": _openai_model(),
    "input": [
      {"role": "system", "content": [{"type": "input_text", "text": system_prompt}]},
      {"role": "user", "content": [{"type": "input_text", "text": json.dumps(user_payload, ensure_ascii=False)}]},
    ],
    "text": {
      "format": {
        "type": "json_schema",
        "name": "q0_anchor_plausibility_review",
        "schema": _anchor_plausibility_review_schema(),
        "strict": True,
      }
    },
  }
  raw_openai_response: Dict[str, Any] = {}
  try:
    resp = _post_openai(
      url="https://api.openai.com/v1/responses",
      headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
      payload=payload,
    )
  except Exception as exc:
    return _anchor_plausibility_failure_payload(
      draft_id=draft_id,
      lever_id=lever_id,
      anchor_context_hash=anchor_context_hash,
      prompt_file=prompt_file,
      status="failed_openai_request",
      detail=str(exc),
      prompt_trace=prompt_trace,
    )
  if resp.status_code >= 400:
    return _anchor_plausibility_failure_payload(
      draft_id=draft_id,
      lever_id=lever_id,
      anchor_context_hash=anchor_context_hash,
      prompt_file=prompt_file,
      status="failed_openai_status",
      detail=resp.text[:1200],
      prompt_trace=prompt_trace,
    )
  raw_openai_response = resp.json() if isinstance(resp.json(), dict) else {"response": resp.text[:4000]}
  parsed = _parse_responses_json_dict(raw_openai_response)
  if not isinstance(parsed, dict):
    return _anchor_plausibility_failure_payload(
      draft_id=draft_id,
      lever_id=lever_id,
      anchor_context_hash=anchor_context_hash,
      prompt_file=prompt_file,
      status="failed_parse",
      detail="Unable to parse Q0 anchor plausibility JSON.",
      prompt_trace=prompt_trace,
      raw_openai_response=raw_openai_response,
    )
  plausibility = str(parsed.get("anchor_plausibility") or "").strip().lower()
  confidence = _safe_float(parsed.get("confidence"))
  reason = str(parsed.get("reason") or "").strip()
  key_factors = [
    str(item).strip()
    for item in (parsed.get("key_factors") or [])
    if str(item).strip()
  ]
  if plausibility not in {"plausible", "implausible", "uncertain"} or confidence is None or not reason:
    return _anchor_plausibility_failure_payload(
      draft_id=draft_id,
      lever_id=lever_id,
      anchor_context_hash=anchor_context_hash,
      prompt_file=prompt_file,
      status="failed_invalid_response",
      detail="Q0 anchor plausibility review returned an invalid structured decision.",
      prompt_trace=prompt_trace,
      raw_openai_response=raw_openai_response,
    )
  return {
    "contract_version": "q0_anchor_plausibility_review_v1",
    "draft_id": str(draft_id or "").strip(),
    "lever_id": str(lever_id or "").strip(),
    "anchor_context_hash": str(anchor_context_hash or "").strip(),
    "status": "completed",
    "prompt_file": prompt_file,
    "review_status": "completed",
    "decision_source": "gpt",
    "detail": "",
    "prompt_trace": copy.deepcopy(prompt_trace),
    "raw_openai_response": copy.deepcopy(raw_openai_response),
    "decision": {
      "anchor_plausibility": plausibility,
      "confidence": float(confidence),
      "reason": reason,
      "key_factors": key_factors,
    },
  }


def _run_q0_anchor_plausibility_review_cached(
  *,
  draft_id: str,
  business_facts: Optional[Dict[str, Any]],
  ops_json: Optional[Dict[str, Any]],
  lever_id: str,
  lever_entry: Optional[Dict[str, Any]],
  q0_value: Any,
  finmo_q0_row: Optional[Dict[str, Any]],
  derived_metrics: Optional[Dict[str, Any]],
  allow_new_call: bool,
) -> Dict[str, Any]:
  user_payload = _q0_anchor_plausibility_user_payload(
    draft_id=draft_id,
    business_facts=copy.deepcopy(business_facts or {}),
    ops_json=copy.deepcopy(ops_json or {}),
    lever_id=lever_id,
    lever_entry=copy.deepcopy(lever_entry or {}),
    q0_value=q0_value,
    finmo_q0_row=copy.deepcopy(finmo_q0_row or {}),
    derived_metrics=copy.deepcopy(derived_metrics or {}),
  )
  anchor_context_hash = _q0_anchor_plausibility_context_hash(
    draft_id=draft_id,
    lever_id=lever_id,
    payload=user_payload,
  )
  cache_key = (str(draft_id or "").strip(), str(lever_id or "").strip(), anchor_context_hash)
  cache = _q0_anchor_plausibility_cache()
  cached = cache.get(cache_key)
  if isinstance(cached, dict):
    cached_payload = copy.deepcopy(cached)
    cached_payload["cache_hit"] = True
    return cached_payload
  if not allow_new_call:
    result = _anchor_plausibility_failure_payload(
      draft_id=draft_id,
      lever_id=lever_id,
      anchor_context_hash=anchor_context_hash,
      prompt_file="client_intake_and_finmo/prompts/anchor_plausibility/reviewer.md",
      status="failed_budget_exhausted",
      detail="Anchor plausibility review budget exhausted before this lever could be evaluated.",
      prompt_trace={"user_payload": copy.deepcopy(user_payload)},
    )
    result["cache_hit"] = False
    cache[cache_key] = copy.deepcopy(result)
    return result
  result = _run_q0_anchor_plausibility_review_openai(
    draft_id=draft_id,
    lever_id=lever_id,
    anchor_context_hash=anchor_context_hash,
    user_payload=user_payload,
  )
  result["cache_hit"] = False
  cache[cache_key] = copy.deepcopy(result)
  return result


